 EditText field(LinearLayout root,String label,String value){TextView t=new TextView(this);t.setText(label);root.addView(t);EditText e=new EditText(this);e.setSingleLine(true);e.setText(value);root.addView(e);return e;}
 String clean(String s){return s.replaceAll("[^A-Za-z0-9 ._-]","");}
 void generate(){pendingId=null;try{int w=(int)Math.round(Double.parseDouble(width.getText().toString())*8),h=(int)Math.round(Double.parseDouble(length.getText().toString())*8);if(w<160||w>432||h<240||h>16000)throw new IllegalArgumentException();String name=clean(heading.getText().toString()),id=clean(asset.getText().toString());if(name.length()>18||id.length()>12||id.isEmpty())throw new IllegalArgumentException();command.setText("^XA\n^PW"+w+"\n^LL"+h+"\n^LH0,0\n^FO16,32^A0N,30,25^FD"+name+"^FS\n^FO16,76^GB"+(w-32)+",3,3^FS\n^FO16,100^A0N,22,18^FDSAMPLE ONLY^FS\n^FO16,132^A0N,20,16^FDNOT A TEST RECORD^FS\n^FO16,170^A0N,20,16^FDTested by: "+(users.getSelectedItemPosition()>0?userInitials.get(users.getSelectedItemPosition()-1):"NOT SELECTED")+"^FS\n^FO16,205^BY1^BCN,48,Y,N,N^FD"+id+"^FS\n^PQ1^XZ");}catch(Exception e){status.setText("Check dimensions (20–54 mm wide, 30–2000 mm long) and sample text lengths.");}}
 String labelText(String s){return s.replaceAll("[^A-Za-z0-9 ._/-]","");}
 void saveTest(){if(!print.isEnabled())return;int u=users.getSelectedItemPosition(),res=result.getSelectedItemPosition();String id=asset.getText().toString().trim();if(u<=0||res==0||!id.matches("[A-Za-z0-9_-]{1,12}")||customer.getText().toString().trim().isEmpty()||site.getText().toString().trim().isEmpty()||description.getText().toString().trim().isEmpty()||(res==1&&interval.getSelectedItemPosition()==0)||(res==2&&fault.getText().toString().trim().isEmpty())){status.setText("Complete customer, site, asset, description, tester, result and interval or failure details.");return;}
 if(res==2){new AlertDialog.Builder(this).setTitle("Failed equipment").setMessage("Remove equipment from service and attach a failed equipment warning. Confirm the recorded result.").setNegativeButton("Cancel",null).setPositiveButton("Confirm failure",(d,i)->recordTest()).show();}else new AlertDialog.Builder(this).setTitle("Confirm PASS").setMessage("Confirm all required inspections and electrical tests have passed.").setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,i)->recordTest()).show();}
 void recordTest(){try{int u=users.getSelectedItemPosition()-1;boolean pass=result.getSelectedItemPosition()==1;java.time.LocalDate today=java.time.LocalDate.now();String due=pass?today.plusMonths(Integer.parseInt(interval.getSelectedItem().toString())).toString():"";String id=asset.getText().toString();String initials=userInitials.get(u);String z="^XA\n^PW352^LL784^LH0,0\n^FO16,24^A0N,32,26^FDELEC.TECH^FS\n^FO16,70^GB320,3,3^FS\n^FO16,88^A0N,30,24^FD"+(pass?"TESTED & PASSED":"FAILED - DO NOT USE")+"^FS\n^FO16,132^A0N,23,20^FDTested: "+today+"^FS\n^FO16,166^A0N,23,20^FD"+(pass?"Due: "+due:"REMOVE FROM SERVICE")+"^FS\n^FO16,200^A0N,23,20^FDTested by: "+initials+"^FS\n^FO16,234^A0N,20,18^FDAS/NZS 3760^FS\n^FO16,270^BY1^BCN,60,Y,N,N^FD"+id+"^FS\n^FO330,650^A0I,36,30^FDELEC.TECH^FS\n^PQ1^XZ";
 org.json.JSONObject o=new org.json.JSONObject();String key=UUID.randomUUID().toString();o.put("id",key);o.put("asset",id);o.put("customer",customer.getText().toString());o.put("site",site.getText().toString());o.put("description",description.getText().toString());o.put("tester",userNames.get(u));o.put("initials",initials);o.put("date",today.toString());o.put("due",due);o.put("result",pass?"PASS":"FAIL");o.put("fault",pass?"":fault.getText().toString());o.put("zpl",z);o.put("printState","Pending");if(!getSharedPreferences("tests",0).edit().putString(key,o.toString()).commit())throw new java.io.IOException("Storage failed");pendingId=key;command.setText(z);send();}catch(Exception e){status.setText("Unable to save test: "+e.getMessage());}}
 void history(){ArrayList<String> keys=new ArrayList<>(),labels=new ArrayList<>();for(java.util.Map.Entry<String,?> e:getSharedPreferences("tests",0).getAll().entrySet())try{org.json.JSONObject o=new org.json.JSONObject(e.getValue().toString());keys.add(e.getKey());labels.add(o.getString("date")+" | "+o.getString("asset")+" | "+o.getString("result")+" | "+o.optString("printState"));}catch(Exception ignored){}if(keys.isEmpty()){status.setText("No saved tests");return;}new AlertDialog.Builder(this).setTitle("Saved tests — select to load tag").setItems(labels.toArray(new String[0]),(d,i)->{try{pendingId=keys.get(i);command.setText(new org.json.JSONObject(getSharedPreferences("tests",0).getString(pendingId,"{}")).getString("zpl"));status.setText("Saved tag loaded. Check existing tag before reprinting.");}catch(Exception ignored){}}).show();}
 void markPrinted(String key){if(key==null)return;new AlertDialog.Builder(this).setTitle("Did the physical tag print?").setNegativeButton("No / uncertain",(d,i)->setPrintState(key,"Pending / uncertain")).setPositiveButton("Yes",(d,i)->setPrintState(key,"Confirmed printed")).show();}
 void setPrintState(String key,String state){try{android.content.SharedPreferences p=getSharedPreferences("tests",0);org.json.JSONObject o=new org.json.JSONObject(p.getString(key,"{}"));o.put("printState",state);p.edit().putString(key,o.toString()).commit();}catch(Exception ignored){}}
 void loadUsers(){userNames.clear();userInitials.clear();try{org.json.JSONArray a=new org.json.JSONArray(getPreferences(0).getString("users","[]"));for(int i=0;i<a.length();i++){org.json.JSONObject o=a.getJSONObject(i);userNames.add(o.getString("name"));userInitials.add(o.getString("initials"));}}catch(Exception ignored){}ArrayList<String> labels=new ArrayList<>();labels.add("Select tester");for(int i=0;i<userNames.size();i++)labels.add(userNames.get(i)+" ("+userInitials.get(i)+")");users.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));users.setSelection(Math.min(labels.size()-1,getPreferences(0).getInt("selectedUser",0)));users.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int i,long id){getPreferences(0).edit().putInt("selectedUser",i).apply();if(command!=null)generate();}});}
 void manageUsers(){ArrayList<String> options=new ArrayList<>(userNames);options.add("Add user");new AlertDialog.Builder(this).setTitle("Manage users").setItems(options.toArray(new String[0]),(d,i)->editUser(i)).show();}
 void editUser(int i){LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText n=field(l,"Name",i<userNames.size()?userNames.get(i):"");EditText a=field(l,"Initials",i<userNames.size()?userInitials.get(i):"");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Tester details").setView(l).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{String name=n.getText().toString().trim(),initial=a.getText().toString().trim().toUpperCase(Locale.ROOT);if(name.isEmpty()||!initial.matches("[A-Z0-9]{1,6}")){a.setError("Enter name and 1–6 letters or digits");return;}if(i<userNames.size()){userNames.set(i,name);userInitials.set(i,initial);}else{userNames.add(name);userInitials.add(initial);}org.json.JSONArray arr=new org.json.JSONArray();try{for(int j=0;j<userNames.size();j++){org.json.JSONObject o=new org.json.JSONObject();o.put("name",userNames.get(j));o.put("initials",userInitials.get(j));arr.put(o);}}catch(Exception e){return;}getPreferences(0).edit().putString("users",arr.toString()).putInt("selectedUser",i+1).apply();loadUsers();dialog.dismiss();}));dialog.show();}
 void load(){if(Build.VERSION.SDK_INT>=31 && checkSelfPermission("android.permission.BLUETOOTH_CONNECT")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.BLUETOOTH_CONNECT"},1);return;} try{BluetoothAdapter a=getSystemService(BluetoothManager.class).getAdapter(); paired.clear(); ArrayList<String> names=new ArrayList<>(); if(a!=null && a.isEnabled())for(BluetoothDevice d:a.getBondedDevices()){paired.add(d);names.add(d.getName()+" ("+d.getAddress()+")");} devices.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));status.setText(names.isEmpty()?"No paired devices. Enable Bluetooth and pair printer.":"Select printer.");}catch(Exception e){status.setText(e.toString());}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)load();}
 void closeSocket(){BluetoothSocket s=socket;socket=null;if(s!=null)try{s.close();}catch(Exception ignored){}}
 void note(String s){runOnUiThread(()->log.append(new java.text.SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date())+" "+s+"\n"));}
 void send(){if(SystemClock.elapsedRealtime()<readyAt){status.setText("Wait for printer startup countdown.");return;}int i=devices.getSelectedItemPosition();if(i<0||i>=paired.size()){status.setText("Select a paired printer.");return;}BluetoothDevice d=paired.get(i);String data=command.getText().toString();final String job=pendingId;int m=mode.getSelectedItemPosition();int wait=new int[]{500,1000,2000}[delay.getSelectedItemPosition()];print.setEnabled(false);disconnect.setEnabled(false);status.setText("Connecting...");
 worker.execute(()->{boolean started=false;Handler h=new Handler(Looper.getMainLooper());Runnable timeout=null;try{
 if(m!=2||socket==null||!socket.isConnected()||!socket.getRemoteDevice().equals(d)){closeSocket();UUID uuid=UUID.fromString("00001101-0000-1000-8000-00805F9B34FB");socket=m==1?d.createInsecureRfcommSocketToServiceRecord(uuid):d.createRfcommSocketToServiceRecord(uuid);}
 final BluetoothSocket s=socket;timeout=()->{try{s.close();}catch(Exception ignored){}};h.postDelayed(timeout,15000);
 if(!s.isConnected()){note("Opening socket");s.connect();note("Socket opened");}
 Thread.sleep(wait);byte[] bytes=(data+"\n").getBytes(StandardCharsets.US_ASCII);started=true;s.getOutputStream().write(bytes);s.getOutputStream().flush();note("Sent "+bytes.length+" bytes");Thread.sleep(wait);
 java.io.InputStream in=s.getInputStream();int n=in.available();if(n>0){byte[] buf=new byte[Math.min(n,4096)];int count=in.read(buf);if(count>0)note("RX: "+new String(buf,0,count,StandardCharsets.US_ASCII));}else note("No response available");
 if(m!=2){closeSocket();note("Socket closed");}runOnUiThread(()->{status.setText("Data sent — verify physical print.");markPrinted(job);});
 }catch(Exception e){closeSocket();note(e.toString());final String msg=started?"Print uncertain — check label before retrying. ":"Not sent — connection failed. ";runOnUiThread(()->status.setText(msg+e.getMessage()));}
 finally{if(timeout!=null)h.removeCallbacks(timeout);runOnUiThread(()->{print.setEnabled(true);disconnect.setEnabled(true);});}});}
 protected void onDestroy(){destroyed=true;closeSocket();worker.shutdownNow();super.onDestroy();}
